tool_calls.arguments:
{"command":"cat > /tmp/nginx-config.yaml << 'EOF'
apiVersion: v1
kind: ConfigMap
metadata:
  name: app-nginx-config
  namespace: default
data:
  nginx.conf: |
    worker_processes auto;
    events {
        worker_connections 1024;
    }
    http {
        server {
            listen 80;
            server_name localhost;

            location / {
                root /usr/share/nginx/html;
                index index.html;
            }

            location /readyz {
                access_log off;
                return 200 "OK\n";
            }
        }
    }
EOF
echo "ConfigMap created""}

